
/* Divi scripts.min.js placeholder - essential functionality */
(function($){
"use strict";
$(document).ready(function(){
  /* Mobile menu toggle */
  $(".mobile_menu_bar").on("click",function(e){
    e.preventDefault();
    var $menu=$("#mobile_menu, .et_mobile_menu");
    if($menu.length===0){
      var $nav=$(".et-menu-nav > ul").clone();
      $nav.attr("id","mobile_menu").addClass("et_mobile_menu");
      $(".mobile_nav").append($nav);
      $menu=$("#mobile_menu");
    }
    $menu.slideToggle(300);
  });
  
  /* Sub-menu toggle on mobile */
  $(document).on("click",".et_mobile_menu .menu-item-has-children > a",function(e){
    e.preventDefault();
    $(this).siblings(".sub-menu").slideToggle(200);
  });

  /* Sticky header */
  if($(".et_pb_section_0_tb_header").length){
    var $header=$(".et_pb_section_0_tb_header");
    $(window).on("scroll",function(){
      if($(window).scrollTop()>100){
        $header.addClass("et_pb_sticky");
      }else{
        $header.removeClass("et_pb_sticky");
      }
    });
  }

  /* FitVids */
  $(".et_pb_section").fitVids&&$(".et_pb_section").fitVids();

  /* Show all sections */
  $(".et_pb_section, .et-waypoint, .et_pb_preload > div").css({"opacity":"1","visibility":"visible"});
});
})(jQuery);
